	return anterior // nueva cabeza
}

func imprimir(n *Nodo) {
	for ; n != nil; n = n.Siguiente {
		fmt.Print(n.Valor, " ")
	}
	fmt.Println()
}

func main() {
	lista := &Nodo{1, &Nodo{2, &Nodo{3, &Nodo{4, nil}}}}
	imprimir(lista)          // 1 2 3 4
	lista = Invertir(lista)
	imprimir(lista)          // 4 3 2 1
}
```

### Cómo funciona

Para `1 → 2 → 3 → nil`:

| Paso | anterior | actual | Resultado parcial |
|------|----------|--------|-------------------|
| inicio | nil | 1 | |
| 1 | 1 | 2 | 1 → nil |
| 2 | 2 | 3 | 2 → 1 → nil |
| 3 | 3 | nil | 3 → 2 → 1 → nil |

Al terminar, `anterior` apunta a la nueva cabeza.

## Versión recursiva (O(n) tiempo, O(n) pila)

```go
func InvertirRec(cabeza *Nodo) *Nodo {
	if cabeza == nil || cabeza.Siguiente == nil {
		return cabeza
	}
	nuevaCabeza := InvertirRec(cabeza.Siguiente)
	cabeza.Siguiente.Siguiente = cabeza // el siguiente apunta de vuelta a mí
	cabeza.Siguiente = nil              // yo paso a ser el final
	return nuevaCabeza
}
```

## Notas

- **Prefiere la iterativa**: usa memoria constante y evita desbordar la pila con listas muy largas.
- Ambas funciones **modifican la lista original**; usa el valor devuelto como nueva cabeza.
- Una lista vacía (`nil`) o de un solo nodo se devuelve tal cual.
- Si usas `container/list` de la biblioteca estándar (lista doblemente enlazada), no hay método de inversión: tendrías que recorrerla y reordenar con `MoveToFront`:

```go
func invertirContainerList(l *list.List) {
	for e := l.Front(); e != nil; {
		siguiente := e.Next()
		l.MoveToFront(e)
		e = siguiente
	}
}
```

